fn solve(a: i8, b: i8, c: i8) -> i8 {
    let nums = [a, b, c];
    let max_val = *nums.iter().max().unwrap();

    let mut min_ops = i8::MAX;
    // We consider targets max_val, max_val+1, max_val+2 as explained.
    for target in max_val..=max_val + 2 {
        let diffs = nums.iter().map(|&x| target - x).collect::<Vec<_>>();
        let sum: i8 = diffs.iter().sum();
        let max_diff = *diffs.iter().max().unwrap();

        // minimal number of operations to cover diffs
        // each operation adds +2 total increments
        // so operations needed >= ceil(sum / 2) and >= max_diff
        let ops = std::cmp::max(max_diff, (sum + 1) / 2);
        if ops < min_ops {
            min_ops = ops;
        }
    }

    min_ops
}